import { Injectable, NgZone } from '@angular/core';
import { MatDialog, MatDialogRef } from '@angular/material/dialog';
import { HttpClient } from '@angular/common/http';
import { Router } from '@angular/router';
import { first } from 'rxjs/operators';
import { API_BASE } from '../api.config';
import { ConfirmDialogComponent, ConfirmDialogData } from '../components/confirm-dialog/confirm-dialog.component';
import { AuthService } from '../../home/service/auth.service';

@Injectable({ providedIn: 'root' })
export class SessionService {
  
  private readonly warningTimeoutMs = 5 * 60 * 1000; // 5-minute countdown grace period (10m + 5m = 15m for User, 25m + 5m = 30m for Admin)
  private get idleTimeoutMs(): number {
    return this.isAdminOrSuperAdmin() ? 25 * 60 * 1000 : 10 * 60 * 1000;
  }
  private readonly activityEvents = ['mousemove', 'mousedown', 'keydown', 'scroll', 'touchstart'];
  private listening = false;
  private lastActivityAt = Date.now();
  private idleTimer: ReturnType<typeof setTimeout> | null = null;
  private countdownInterval: ReturnType<typeof setInterval> | null = null;
  private warningDialogRef: MatDialogRef<ConfirmDialogComponent> | null = null;
  private promptOpen = false;
  private refreshInProgress = false;
  private isLoggingOut = false;

  constructor(
    private dialog: MatDialog,
    private http: HttpClient,
    private router: Router,
    private ngZone: NgZone,
    private auth: AuthService
  ) {}

  startListening() {
    if (this.listening) return;
    this.listening = true;

    this.activityEvents.forEach(eventName => {
      window.addEventListener(eventName, () => this.recordActivity(), { passive: true });
    });

    window.addEventListener('sessionExpired', (ev: any) => {
      if (this.isLoggingOut || !this.hasLoggedInSession()) return;
      let msg = ev && ev.detail && ev.detail.message ? String(ev.detail.message) : 'Your session has expired';
      if (/pyodbc|operationalerror|sql server|tcp provider|sqlalchemy|traceback/i.test(msg)) {
        msg = 'Your session has expired';
      }
      if (/another device|logged in from another|active on another/i.test(msg)) {
        this.ngZone.run(() => this.promptSingleDeviceLogout('Your account was logged in from another device. Please log in again if needed.'));
      } else {
        this.ngZone.run(() => this.promptExtendOrLogout(msg));
      }
    });

    this.scheduleIdleCheck();
  }

  private promptSingleDeviceLogout(message: string) {
    if (this.isLoggingOut || this.promptOpen || !this.hasLoggedInSession()) return;
    this.stopCountdown();
    this.promptOpen = true;

    const ref = this.dialog.open(ConfirmDialogComponent, {
      data: {
        title: 'Logged Out',
        message: message,
        confirmText: 'OK',
        cancelText: ''
      },
      disableClose: true
    });

    ref.afterClosed().pipe(first()).subscribe(() => {
      this.promptOpen = false;
      this.clearAndRedirect();
    });
  }

  private promptExtendOrLogout(message: string) {
    if (this.isLoggingOut || this.promptOpen || !this.hasLoggedInSession()) return;
    this.stopCountdown();
    this.promptOpen = true;

    const ref = this.dialog.open(ConfirmDialogComponent, {
      data: {
        title: 'Session Expired',
        message: message + '\nWould you like to continue your session?',
        confirmText: 'Continue',
        cancelText: 'Logout'
      },
      disableClose: true
    });

    ref.afterClosed().pipe(first()).subscribe((ok: boolean) => {
      this.promptOpen = false;
      if (ok === true) {
        this.lastActivityAt = Date.now();
        this.tryRefreshToken();
        this.scheduleIdleCheck();
      } else {
        this.doLogout();
      }
    });
  }

  private promptWarning() {
    if (this.isLoggingOut || this.promptOpen || !this.hasLoggedInSession()) return;
    this.promptOpen = true;

    const logoutTime = Date.now() + this.warningTimeoutMs;
    const dialogData: ConfirmDialogData = {
      title: 'Session Expiring',
      message: 'You have been inactive. You will be logged out in:',
      confirmText: 'Stay Logged In',
      cancelText: 'Logout',
      countdown: '05:00'
    };

    this.updateCountdownDisplay(dialogData, logoutTime);

    this.warningDialogRef = this.dialog.open(ConfirmDialogComponent, {
      data: dialogData,
      disableClose: true
    });

    this.countdownInterval = setInterval(() => {
      const remainingSec = Math.ceil((logoutTime - Date.now()) / 1000);
      if (remainingSec <= 0) {
        this.stopCountdown();
        this.ngZone.run(() => {
          if (this.warningDialogRef) {
            try { this.warningDialogRef.close(false); } catch (e) {}
          }
          this.doLogout();
        });
      } else {
        this.ngZone.run(() => {
          this.updateCountdownDisplay(dialogData, logoutTime);
        });
      }
    }, 1000);

    this.warningDialogRef.afterClosed().pipe(first()).subscribe((stayLoggedIn: boolean) => {
      this.stopCountdown();
      this.warningDialogRef = null;
      this.promptOpen = false;

      if (stayLoggedIn === true) {
        this.lastActivityAt = Date.now();
        this.tryRefreshToken();
        this.scheduleIdleCheck();
      } else {
        this.doLogout();
      }
    });
  }

  private updateCountdownDisplay(dialogData: ConfirmDialogData, logoutTime: number): void {
    const remainingSec = Math.max(0, Math.ceil((logoutTime - Date.now()) / 1000));
    const minutes = Math.floor(remainingSec / 60);
    const seconds = remainingSec % 60;
    const mm = minutes < 10 ? '0' + minutes : '' + minutes;
    const ss = seconds < 10 ? '0' + seconds : '' + seconds;
    dialogData.countdown = `${mm}:${ss}`;
  }

  private stopCountdown(): void {
    if (this.countdownInterval) {
      clearInterval(this.countdownInterval);
      this.countdownInterval = null;
    }
  }

  private tryRefreshToken() {
    if (this.refreshInProgress || !this.hasLoggedInSession()) return;
    this.refreshInProgress = true;
    const raw = sessionStorage.getItem('user');
    let userId = null;
    if (raw) {
      try { userId = JSON.parse(raw).user_id || JSON.parse(raw).userId || null; } catch(e) { userId = null; }
    }
    const url = `${API_BASE}/refresh-token`;
    const payload: any = {};
    if (userId) payload.user_id = userId;

    this.http.post<any>(url, payload).pipe(first()).subscribe({
      next: (res) => {
        try {
          if (res && res.token) {
            console.debug('[SessionService] Token refreshed successfully. Updated sessionStorage token:', res.token.substring(0, 8) + '...');
            sessionStorage.setItem('token', res.token);
          }
          if (res && res.user) {
            sessionStorage.setItem('user', JSON.stringify(res.user));
          }
        } catch (e) {}
      },
      error: (err) => {
        this.refreshInProgress = false;
        if (err && (err.status === 401 || err.status === 403)) {
          const msg = err.error && (err.error.statusMessage || err.error.message) 
            ? err.error.statusMessage || err.error.message 
            : 'Your session could not be renewed. Please log in again.';
          this.ngZone.run(() => this.promptSingleDeviceLogout(msg));
        } else {
          console.warn('Unable to refresh the session; keeping existing login state.', err);
        }
      },
      complete: () => {
        this.refreshInProgress = false;
      }
    });
  }

  private recordActivity(): void {
    if (this.promptOpen || this.isLoggingOut) return;
    this.lastActivityAt = Date.now();
    if (!this.idleTimer) this.scheduleIdleCheck();
  }

  private scheduleIdleCheck(): void {
    if (this.idleTimer) clearTimeout(this.idleTimer);
    if (this.isLoggingOut) return;

    const remainingMs = Math.max(0, this.idleTimeoutMs - (Date.now() - this.lastActivityAt));
    this.idleTimer = setTimeout(() => {
      this.idleTimer = null;
      if (this.isLoggingOut) return;
      if (!this.hasBeenIdle()) {
        this.scheduleIdleCheck();
        return;
      }

      this.ngZone.run(() => {
        this.promptWarning();
      });
    }, remainingMs);
  }

  private isAdminOrSuperAdmin(): boolean {
    try {
      const raw = sessionStorage.getItem('user');
      let role = '';
      if (raw) {
        const user = JSON.parse(raw);
        role = String(user.role || user.user_role || sessionStorage.getItem('userRole') || '').toLowerCase();
      } else {
        const u = this.auth?.currentUserValue;
        if (u) role = String(u.role || u.user_role || '').toLowerCase();
      }
      return ['admin', 'super_admin', 'superadmin', 'super-admin'].includes(role);
    } catch (e) {
      return false;
    }
  }

  private hasBeenIdle(): boolean {
    return Date.now() - this.lastActivityAt >= this.idleTimeoutMs;
  }

  private hasLoggedInSession(): boolean {
    try {
      return !!sessionStorage.getItem('token') && !!sessionStorage.getItem('user');
    } catch (e) {
      return false;
    }
  }

  private doLogout() {
    if (this.isLoggingOut) return;
    this.clearAndRedirect();
  }

  private clearAndRedirect() {
    this.isLoggingOut = true;
    this.stopCountdown();
    if (this.idleTimer) clearTimeout(this.idleTimer);
    this.idleTimer = null;
    this.promptOpen = false;
    this.refreshInProgress = false;

    try {
      this.auth.logout();
    } catch (e) {
      try {
        sessionStorage.removeItem('token');
        sessionStorage.removeItem('user');
        sessionStorage.removeItem('isLogin');
        sessionStorage.removeItem('userRole');
      } catch (e) {}
    }

    this.ngZone.run(() => {
      try { this.dialog.closeAll(); } catch (e) {}
      
      this.router.navigate(['/login']).then(navigated => {
        if (!navigated) {
          window.location.href = '/login';
        }
      }).catch(() => {
        window.location.href = '/login';
      });
    });
  }
}

